macro_rules! generate_rule {
    () => {
        fn generate_rule (rule : OptimizedRule) -> TokenStream { let name = format_ident ! ("r#{}" , rule . name) ; let expr = if rule . ty == RuleType :: Atomic || rule . ty == RuleType :: CompoundAtomic { generate_expr_atomic (rule . expr) } else if rule . name == "WHITESPACE" || rule . name == "COMMENT" { let atomic = generate_expr_atomic (rule . expr) ; quote ! { state . atomic (:: pest :: Atomicity :: Atomic , | state | { # atomic }) } } else { generate_expr (rule . expr) } ; let box_ty = box_type () ; match rule . ty { RuleType :: Normal => quote ! { # [inline] # [allow (non_snake_case , unused_variables)] pub fn # name (state : # box_ty <:: pest :: ParserState <'_ , Rule >>) -> :: pest :: ParseResult <# box_ty <:: pest :: ParserState <'_ , Rule >>> { state . rule (Rule ::# name , | state | { # expr }) } } , RuleType :: Silent => quote ! { # [inline] # [allow (non_snake_case , unused_variables)] pub fn # name (state : # box_ty <:: pest :: ParserState <'_ , Rule >>) -> :: pest :: ParseResult <# box_ty <:: pest :: ParserState <'_ , Rule >>> { # expr } } , RuleType :: Atomic => quote ! { # [inline] # [allow (non_snake_case , unused_variables)] pub fn # name (state : # box_ty <:: pest :: ParserState <'_ , Rule >>) -> :: pest :: ParseResult <# box_ty <:: pest :: ParserState <'_ , Rule >>> { state . rule (Rule ::# name , | state | { state . atomic (:: pest :: Atomicity :: Atomic , | state | { # expr }) }) } } , RuleType :: CompoundAtomic => quote ! { # [inline] # [allow (non_snake_case , unused_variables)] pub fn # name (state : # box_ty <:: pest :: ParserState <'_ , Rule >>) -> :: pest :: ParseResult <# box_ty <:: pest :: ParserState <'_ , Rule >>> { state . atomic (:: pest :: Atomicity :: CompoundAtomic , | state | { state . rule (Rule ::# name , | state | { # expr }) }) } } , RuleType :: NonAtomic => quote ! { # [inline] # [allow (non_snake_case , unused_variables)] pub fn # name (state : # box_ty <:: pest :: ParserState <'_ , Rule >>) -> :: pest :: ParseResult <# box_ty <:: pest :: ParserState <'_ , Rule >>> { state . atomic (:: pest :: Atomicity :: NonAtomic , | state | { state . rule (Rule ::# name , | state | { # expr }) }) } } , } }
    };
}

generate_rule!();